style.css:
@-moz-document domain("instagram.com"), url-prefix("https://www.instagram.com/") {
/* General Background */
    body, html, ._a3wf, ._a3we, ._a3wg {
        background-color: #fce4ec !important; /* Soft blush pink */
        color: #5a5a5a !important; /* Neutral gray text */
    }

    /* Headers and Navigation Bars */
    ._ab6- {
        background-color: #ec9ec0 !important; /* Accent pink */
        border-bottom: 1px solid #f3dce5 !important; /* Subtle pink divider */
    }

    /* Sidebar and Modals */
    ._aa4a, ._aaqg, ._aa4f {
        background-color: #fde6ef !important; /* Light blush pink */
        color: #5a5a5a !important;
    }

    /* Post Background */
    ._aagu, ._aagv {
        background-color: #fff0f5 !important; /* Very light pink for posts */
    }

    /* Buttons */
    ._a9--, ._a9-_ {
        background-color: #ec9ec0 !important; /* Pink button background */
        color: white !important; /* White text */
        border-radius: 5px !important;
    }

    ._a9--:hover, ._a9-_:hover {
        background-color: #d78ba9 !important; /* Darker pink on hover */
    }

    /* Links and Text */
    a, ._aa8k, ._aa8m {
        color: #ec9ec0 !important; /* Accent pink for links */
    }

    a:hover {
        color: #d78ba9 !important; /* Darker pink for link hover */
    }

    /* Stories Section */
    ._aa64 {
        background: linear-gradient(90deg, #ec9ec0, #f8e3eb) !important; /* Pink gradient for stories */
        border-radius: 12px !important;
    }

    /* Chat (Direct Messages) Background */
    ._ab4a, ._ab4z, ._ab7f, ._abm4, ._abm5, ._abm6 {
        background-color: #fde6ef !important; /* Light blush pink */
        color: #5a5a5a !important;
    }

    ._ab4c, ._ab4d, ._abm9 {
        background-color: #fcd9e6 !important; /* Softer pink for individual chat boxes */
        border-radius: 12px !important;
        color: #5a5a5a !important;
    }

    ._ab4c:focus, ._ab4d:focus {
        background-color: #ec9ec0 !important; /* Accent pink when typing */
    }

    /* Chat Bubble Colors */
    ._aacl {
        background-color: #fff0f5 !important; /* Very light pink for messages */
        color: #5a5a5a !important;
    }

    /* Send Button */
    ._abl- {
        background-color: #ec9ec0 !important; /* Accent pink send button */
        color: white !important;
    }

    ._abl-:hover {
        background-color: #d78ba9 !important; /* Darker pink on hover */
    }

    /* Post Comments and Likes */
    ._a9zr, ._a9zy {
        color: #ec9ec0 !important; /* Pink icons */
    }

    /* Footer Background */
    footer {
        background-color: #fde6ef !important;
        color: #5a5a5a !important;
    }

    /* Search Bar */
    ._aawc, ._aawd {
        background-color: #fde6ef !important;
        border: 1px solid #ec9ec0 !important;
        color: #5a5a5a !important;
    }

    ._aawc:focus, ._aawd:focus {
        background-color: #fcd9e6 !important;
    }

    /* Scrollbars */
    ::-webkit-scrollbar {
        width: 8px;
    }

    ::-webkit-scrollbar-thumb {
        background-color: #ec9ec0;
        border-radius: 10px;
    }

    ::-webkit-scrollbar-track {
        background-color: #fde6ef;
    }

    /* Story Posting Modal */
    ._aa0m, ._aa0q {
        background-color: #fde6ef !important; /* Light blush pink for story modal */
        color: #5a5a5a !important;
        border-radius: 12px !important;
    }

    /* Story Buttons */
    ._aa0o, ._aa0p {
        background-color: #ec9ec0 !important; /* Pink buttons */
        color: white !important;
    }

    ._aa0o:hover, ._aa0p:hover {
        background-color: #d78ba9 !important; /* Darker pink on hover */
    }

    /* Story Text Input */
    ._aa0n {
        background-color: #fff0f5 !important; /* Light pink for text field */
        border: 1px solid #ec9ec0 !important;
        color: #5a5a5a !important;
    }

    ._aa0n:focus {
        background-color: #fcd9e6 !important;
    }
}
